"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { updateProductStock, setProductSpecial, setProductHealthy, Product } from "@/lib/products";
import { Category } from "@/lib/categories";
import ProductFormModal from "./ProductFormModal";
import CloverPanel from "./CloverPanel";
import CategoryReviewPanel from "./CategoryReviewPanel";
import CategoryManagerPanel from "./CategoryManagerPanel";
import { staffFetch } from "@/lib/staff-auth";

function StockStepper({
  product,
  onSaved,
}: {
  product: Product;
  onSaved: (id: string, stock: number) => void;
}) {
  const [value, setValue] = useState(product.stock);
  const [saving, setSaving] = useState(false);
  const lastEditRef = useRef(0);
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Stay in sync with external changes (another tab, a real order coming
  // in) — but not while the user just touched this row themselves.
  useEffect(() => {
    if (Date.now() - lastEditRef.current > 1500) {
      setValue(product.stock);
    }
  }, [product.stock]);

  const commit = (next: number) => {
    const clamped = Math.max(0, Math.floor(next));
    lastEditRef.current = Date.now();
    setValue(clamped);
    if (timerRef.current) clearTimeout(timerRef.current);
    setSaving(true);
    timerRef.current = setTimeout(async () => {
      const ok = await updateProductStock(product.id, clamped);
      setSaving(false);
      if (ok) onSaved(product.id, clamped);
    }, 350);
  };

  return (
    <div className="flex items-center gap-1.5">
      <button
        onClick={() => commit(value - 1)}
        aria-label="Decrease stock"
        className="flex h-7 w-7 items-center justify-center rounded border border-line font-mono text-sm text-ink hover:border-green hover:text-green"
      >
        −
      </button>
      <input
        type="number"
        min={0}
        value={value}
        onChange={(e) => commit(Number(e.target.value))}
        className="w-16 rounded border border-line bg-paper px-2 py-1 text-center font-mono text-sm text-ink outline-none focus:border-green"
      />
      <button
        onClick={() => commit(value + 1)}
        aria-label="Increase stock"
        className="flex h-7 w-7 items-center justify-center rounded border border-line font-mono text-sm text-ink hover:border-green hover:text-green"
      >
        +
      </button>
      <span className={`w-10 font-mono text-[0.62rem] text-ink-soft transition-opacity ${saving ? "opacity-100" : "opacity-0"}`}>
        saving…
      </span>
    </div>
  );
}

type SortMode = "low-stock" | "name";

const ROW_PAGE = 100;

type ModalState = { mode: "create" } | { mode: "edit"; product: Product } | null;

export default function InventoryPanel({
  products,
  categories,
  onStockSaved,
  onProductSaved,
  onProductRemoved,
  onRefresh,
  salesVelocity,
  initialSearch = "",
}: {
  products: Product[];
  categories: Category[];
  onStockSaved: (id: string, stock: number) => void;
  onProductSaved: (product: Product) => void;
  onProductRemoved: (id: string) => void;
  onRefresh: () => void;
  salesVelocity: Record<string, number>;
  initialSearch?: string;
}) {
  const [search, setSearch] = useState(initialSearch);
  const [showCategories, setShowCategories] = useState(false);
  // The product list starts folded away (thousands of rows) — it opens when
  // staff search, pick a category, or tap "Show all products".
  const [showList, setShowList] = useState(false);
  const [category, setCategory] = useState<string>("All");
  const categoryNames = useMemo(() => categories.map((c) => c.name), [categories]);
  const [sort, setSort] = useState<SortMode>("low-stock");
  // The real catalog is thousands of items — list a manageable number at a
  // time (search or pick a category to narrow it down).
  const [rowLimit, setRowLimit] = useState(ROW_PAGE);
  const [modal, setModal] = useState<ModalState>(null);
  const [togglingSpecial, setTogglingSpecial] = useState<string | null>(null);
  const [togglingHealthy, setTogglingHealthy] = useState<string | null>(null);
  const [generatingPhotos, setGeneratingPhotos] = useState(false);
  const [photoResult, setPhotoResult] = useState<string | null>(null);
  const [findingPhotos, setFindingPhotos] = useState(false);
  const [findResult, setFindResult] = useState<string | null>(null);

  const missingPhotoCount = useMemo(() => products.filter((p) => !p.image_url).length, [products]);

  // One-off sweep over every product currently missing a photo — including
  // ones Clover sync never touches at all (a product never linked to
  // Clover, like an old sample item, or one added by hand). Separate from
  // the automatic per-item generation Clover sync/webhook already do; see
  // app/api/products/generate-missing-photos/route.ts.
  const handleGenerateMissingPhotos = async () => {
    setGeneratingPhotos(true);
    setPhotoResult(null);
    try {
      const res = await staffFetch("/api/products/generate-missing-photos", { method: "POST" });
      const body = await res.json();
      if (res.ok) {
        if (body.eligible === 0) {
          setPhotoResult("Every product already has a photo.");
        } else {
          let message = `${body.generated} of ${body.eligible} photo${body.eligible === 1 ? "" : "s"} generated`;
          if (body.failed > 0) message += `, ${body.failed} failed — check Vercel's function logs for why`;
          message += ".";
          setPhotoResult(message);
        }
        onRefresh();
      } else {
        setPhotoResult(body.error || "Couldn't generate photos.");
      }
    } catch {
      setPhotoResult("Couldn't generate photos — check your connection.");
    }
    setGeneratingPhotos(false);
  };

  // Free real package photos by barcode (Open Food Facts) — see
  // app/api/products/find-photos and lib/photo-lookup.ts.
  const handleFindPhotos = async () => {
    setFindingPhotos(true);
    setFindResult("Looking up photos by barcode — this can take a few minutes…");
    try {
      const res = await staffFetch("/api/products/find-photos", { method: "POST" });
      const body = await res.json();
      if (res.ok) {
        setFindResult(
          `Checked ${body.checked} item${body.checked === 1 ? "" : "s"}, found ${body.found} photo${body.found === 1 ? "" : "s"}.` +
            (body.remaining > 0 ? ` ${body.remaining} still to check — click again to continue (it also keeps going on its own in the background).` : " All items with a barcode have been checked.")
        );
        onRefresh();
      } else {
        setFindResult(body.error || "Couldn't look up photos.");
      }
    } catch {
      setFindResult("Couldn't look up photos — check your connection.");
    }
    setFindingPhotos(false);
  };

  const handleToggleSpecial = async (product: Product) => {
    setTogglingSpecial(product.id);
    await setProductSpecial(product.id, !product.is_special);
    setTogglingSpecial(null);
    onRefresh();
  };

  const handleToggleHealthy = async (product: Product) => {
    setTogglingHealthy(product.id);
    await setProductHealthy(product.id, !product.is_healthy);
    setTogglingHealthy(null);
    onRefresh();
  };

  const matching = useMemo(() => {
    let list = products;
    if (category !== "All") list = list.filter((p) => p.category === category);
    if (search.trim()) {
      const q = search.trim().toLowerCase();
      list = list.filter((p) => p.name.toLowerCase().includes(q));
    }
    list = [...list];
    if (sort === "low-stock") {
      list.sort((a, b) => a.stock - b.stock);
    } else {
      list.sort((a, b) => a.name.localeCompare(b.name));
    }
    return list;
  }, [products, category, search, sort]);
  const shown = matching.slice(0, rowLimit);
  const listOpen = showList || Boolean(search.trim()) || category !== "All";

  return (
    <div>
      <CloverPanel onSynced={onRefresh} />

      <CategoryReviewPanel categories={categories} onResolved={onRefresh} />
      <CategoryManagerPanel categories={categories} products={products} onChanged={onRefresh} />

      <div className="mb-4 flex flex-wrap items-center gap-3 rounded-lg border border-line bg-panel p-4">
        <div>
          <p className="font-mono text-[0.65rem] uppercase tracking-wide text-ink-soft">Product Photos</p>
          <p className="mt-1 font-body text-sm text-ink-soft">
            {missingPhotoCount > 0
              ? `${missingPhotoCount.toLocaleString()} items have no photo yet. Real package photos are found free by barcode; tap a product to upload your own.`
              : "Every product has a photo."}
          </p>
        </div>
        <div className="ml-auto flex flex-wrap items-center gap-2">
          {missingPhotoCount > 0 && (
            <button
              onClick={handleFindPhotos}
              disabled={findingPhotos}
              className="rounded-full bg-green px-3.5 py-1.5 font-mono text-xs font-semibold text-white transition hover:bg-green-deep disabled:opacity-60"
            >
              {findingPhotos ? "Finding photos…" : "Find product photos (free)"}
            </button>
          )}
          {/* AI generation costs money per image — only offered once the
              missing list is small enough to be deliberate about. */}
          {missingPhotoCount > 0 && missingPhotoCount <= 25 && (
            <button
              onClick={handleGenerateMissingPhotos}
              disabled={generatingPhotos}
              className="rounded-full border border-line bg-paper px-3.5 py-1.5 font-mono text-xs font-semibold text-ink-soft transition hover:border-gold-ink hover:text-gold-ink disabled:opacity-60"
            >
              {generatingPhotos
                ? "Generating…"
                : `✦ Generate ${missingPhotoCount} missing product photo${missingPhotoCount === 1 ? "" : "s"}`}
            </button>
          )}
        </div>
        {(photoResult || findResult) && (
          <div className="w-full font-body text-xs text-ink-soft">
            {findResult && <p>{findResult}</p>}
            {photoResult && <p>{photoResult}</p>}
          </div>
        )}
      </div>

      <div className="flex flex-wrap items-center gap-2">
        <input
          type="text"
          value={search}
          onChange={(e) => {
            setSearch(e.target.value);
            setRowLimit(ROW_PAGE);
          }}
          placeholder="Search products…"
          className="rounded-full border border-line bg-paper px-4 py-1.5 font-body text-sm text-ink outline-none focus:border-green"
        />
        {/* Category filter — collapsed behind one button, since a real
            catalog has dozens of categories and a wall of chips is busy. */}
        <button
          type="button"
          onClick={() => setShowCategories((v) => !v)}
          aria-expanded={showCategories}
          className={`flex items-center gap-1.5 rounded-full border px-3.5 py-1.5 font-mono text-xs font-semibold transition ${
            category !== "All" ? "border-green bg-green text-white" : "border-line text-ink-soft hover:border-green hover:text-green"
          }`}
        >
          {category === "All" ? "All categories" : category}
          <span aria-hidden className={`transition-transform ${showCategories ? "rotate-180" : ""}`}>▾</span>
        </button>
        {category !== "All" && (
          <button
            type="button"
            onClick={() => {
              setCategory("All");
              setRowLimit(ROW_PAGE);
            }}
            className="font-mono text-[0.65rem] uppercase tracking-wide text-ink-soft hover:text-green"
          >
            Clear
          </button>
        )}
        <div className="ml-auto flex items-center gap-3">
          <div className="flex items-center gap-1.5">
            <span className="font-mono text-[0.65rem] uppercase tracking-wide text-ink-soft">Sort</span>
            <select
              value={sort}
              onChange={(e) => setSort(e.target.value as SortMode)}
              className="rounded border border-line bg-paper px-2 py-1 font-mono text-xs text-ink outline-none focus:border-green"
            >
              <option value="low-stock">Low stock first</option>
              <option value="name">Name (A–Z)</option>
            </select>
          </div>
          <button
            onClick={() => setModal({ mode: "create" })}
            className="rounded-full bg-green px-3.5 py-1.5 font-mono text-xs font-semibold text-white transition hover:bg-green-deep"
          >
            + Add Product
          </button>
        </div>
      </div>

      {showCategories && (
        <div className="mt-3 flex flex-wrap gap-1.5 rounded-lg border border-line bg-panel p-3">
          {["All", ...categoryNames].map((c) => (
            <button
              key={c}
              onClick={() => {
                setCategory(c);
                setRowLimit(ROW_PAGE);
                setShowCategories(false);
              }}
              className={`rounded-full border px-3 py-1 font-mono text-xs font-semibold transition ${
                category === c
                  ? "border-green bg-green text-white"
                  : "border-line bg-paper text-ink-soft hover:border-green hover:text-green"
              }`}
            >
              {c === "All" ? "All categories" : c}
            </button>
          ))}
        </div>
      )}

      {(() => {
        const filtered = Boolean(search.trim()) || category !== "All";
        return (
          <button
            type="button"
            onClick={() => {
              if (filtered && listOpen) {
                setSearch("");
                setCategory("All");
                setShowList(false);
              } else {
                setShowList((v) => !v);
              }
            }}
            aria-expanded={listOpen}
            className="mt-4 flex w-full items-center justify-between rounded-lg border border-line bg-panel px-4 py-3 text-left transition hover:border-green/50"
          >
            <span className="font-mono text-[0.65rem] uppercase tracking-wide text-ink-soft">
              {filtered
                ? `${matching.length.toLocaleString()} matching product${matching.length === 1 ? "" : "s"}`
                : `All products · ${products.length.toLocaleString()}`}
            </span>
            <span className="flex items-center gap-1.5 font-mono text-xs font-semibold text-green">
              {listOpen ? (filtered ? "Clear & hide" : "Hide list") : "Show all products"}
              <span aria-hidden className={`transition-transform ${listOpen ? "rotate-180" : ""}`}>▾</span>
            </span>
          </button>
        );
      })()}

      {listOpen && (
        <>
      {/* Mobile: stacked cards with a large tappable photo. The table below
          is fine on wider screens, but forcing a 720px-wide table onto a
          ~375px phone shrinks everything (including the photo) down to fit,
          which is what made photos hard to see on mobile — a bigger fixed
          pixel size alone didn't fix that, since the table's own layout was
          still squeezing the column. This layout sidesteps that entirely. */}
      <div className="mt-4 flex flex-col gap-2.5 sm:hidden">
        {shown.map((p) => {
          const outOfStock = p.stock === 0;
          const lowStock = p.stock > 0 && p.stock <= 3;
          const velocity = salesVelocity[p.id] ?? 0;
          const daysLeft = velocity > 0 ? p.stock / velocity : null;
          const urgentPace = !outOfStock && daysLeft !== null && daysLeft <= 5;
          return (
            <div key={p.id} className="flex gap-3 rounded-lg border border-line bg-panel p-3">
              <button
                type="button"
                onClick={() => setModal({ mode: "edit", product: p })}
                aria-label={`Edit ${p.name}`}
                className="block h-24 w-24 shrink-0 overflow-hidden rounded-lg transition active:opacity-80"
              >
                {p.image_url ? (
                  // eslint-disable-next-line @next/next/no-img-element
                  <img src={p.image_url} alt="" className="h-full w-full object-cover" />
                ) : (
                  <div className="h-full w-full" style={{ backgroundColor: p.swatch }} />
                )}
              </button>
              <div className="min-w-0 flex-1">
                <p className="font-body text-sm text-ink">
                  {p.name}
                  {p.is_special && (
                    <span className="ml-2 rounded-full bg-gold-tint px-2 py-0.5 font-mono text-[0.6rem] font-semibold uppercase tracking-wide text-gold-ink">
                      Special
                    </span>
                  )}
                  {p.is_healthy && (
                    <span className="ml-2 rounded-full bg-green-tint px-2 py-0.5 font-mono text-[0.6rem] font-semibold uppercase tracking-wide text-green-deep">
                      Healthy Pick
                    </span>
                  )}
                </p>
                <p className="mt-0.5 font-mono text-xs text-ink-soft">
                  {p.category} · ${p.price.toFixed(2)}
                </p>
                <div className="mt-2 flex items-center gap-2">
                  <StockStepper product={p} onSaved={onStockSaved} />
                  {outOfStock && (
                    <span className="font-mono text-[0.62rem] font-semibold uppercase tracking-wide text-[#a8461a]">
                      Out
                    </span>
                  )}
                  {lowStock && (
                    <span className="font-mono text-[0.62rem] font-semibold uppercase tracking-wide text-[#a8461a]">
                      Low
                    </span>
                  )}
                </div>
                {urgentPace && (
                  <p className="mt-1 font-mono text-[0.62rem] text-[#a8461a]">
                    Selling ~{velocity.toFixed(1)}/day — ~{Math.max(1, Math.round(daysLeft!))}d left at this pace
                  </p>
                )}
                <div className="mt-2 flex flex-wrap items-center gap-x-3 gap-y-1">
                  <button
                    onClick={() => setModal({ mode: "edit", product: p })}
                    className="font-mono text-[0.65rem] uppercase tracking-wide text-ink-soft hover:text-green"
                  >
                    Edit
                  </button>
                  <button
                    onClick={() => handleToggleSpecial(p)}
                    disabled={togglingSpecial === p.id}
                    className="font-mono text-[0.6rem] uppercase tracking-wide text-ink-soft hover:text-gold-ink disabled:opacity-60"
                  >
                    {p.is_special ? "Unset Special" : "Make Special"}
                  </button>
                  <button
                    onClick={() => handleToggleHealthy(p)}
                    disabled={togglingHealthy === p.id}
                    className="font-mono text-[0.6rem] uppercase tracking-wide text-ink-soft hover:text-green disabled:opacity-60"
                  >
                    {p.is_healthy ? "Unset Healthy Pick" : "Mark Healthy Pick"}
                  </button>
                </div>
              </div>
            </div>
          );
        })}
        {shown.length === 0 && (
          <p className="rounded-lg border border-line bg-panel px-4 py-6 text-center font-body text-sm text-ink-soft">
            No products match.
          </p>
        )}
      </div>

      {/* Tablet/desktop: the original table. */}
      <div className="mt-4 hidden overflow-x-auto rounded-lg border border-line sm:block">
        <table className="w-full min-w-[720px] border-collapse font-body text-sm">
          <thead>
            <tr className="border-b border-line bg-panel text-left">
              <th className="px-4 py-2.5"></th>
              <th className="px-4 py-2.5 font-mono text-[0.68rem] uppercase tracking-wide text-ink-soft">Product</th>
              <th className="px-4 py-2.5 font-mono text-[0.68rem] uppercase tracking-wide text-ink-soft">Category</th>
              <th className="px-4 py-2.5 font-mono text-[0.68rem] uppercase tracking-wide text-ink-soft">Price</th>
              <th className="px-4 py-2.5 font-mono text-[0.68rem] uppercase tracking-wide text-ink-soft">Stock</th>
              <th className="px-4 py-2.5"></th>
            </tr>
          </thead>
          <tbody>
            {shown.map((p) => {
              const outOfStock = p.stock === 0;
              const lowStock = p.stock > 0 && p.stock <= 3;
              const velocity = salesVelocity[p.id] ?? 0;
              const daysLeft = velocity > 0 ? p.stock / velocity : null;
              const urgentPace = !outOfStock && daysLeft !== null && daysLeft <= 5;
              return (
                <tr key={p.id} className="border-b border-line last:border-none">
                  <td className="px-4 py-2.5">
                    <button
                      type="button"
                      onClick={() => setModal({ mode: "edit", product: p })}
                      aria-label={`Edit ${p.name}`}
                      className="block shrink-0 rounded transition hover:opacity-80 focus:outline-none focus:ring-2 focus:ring-green"
                    >
                      {p.image_url ? (
                        // eslint-disable-next-line @next/next/no-img-element
                        <img
                          src={p.image_url}
                          alt=""
                          className="h-14 w-14 rounded object-cover"
                        />
                      ) : (
                        <div
                          className="h-14 w-14 rounded"
                          style={{ backgroundColor: p.swatch }}
                        />
                      )}
                    </button>
                  </td>
                  <td className="px-4 py-2.5 text-ink">
                    {p.name}
                    {p.is_special && (
                      <span className="ml-2 rounded-full bg-gold-tint px-2 py-0.5 font-mono text-[0.6rem] font-semibold uppercase tracking-wide text-gold-ink">
                        Special
                      </span>
                    )}
                    {p.is_healthy && (
                      <span className="ml-2 rounded-full bg-green-tint px-2 py-0.5 font-mono text-[0.6rem] font-semibold uppercase tracking-wide text-green-deep">
                        Healthy Pick
                      </span>
                    )}
                  </td>
                  <td className="px-4 py-2.5 text-ink-soft">{p.category}</td>
                  <td className="px-4 py-2.5 font-mono text-ink-soft">${p.price.toFixed(2)}</td>
                  <td className="px-4 py-2.5">
                    <div className="flex flex-col gap-1.5">
                      <div className="flex items-center gap-2">
                        <StockStepper product={p} onSaved={onStockSaved} />
                        {outOfStock && (
                          <span className="font-mono text-[0.62rem] font-semibold uppercase tracking-wide text-[#a8461a]">
                            Out
                          </span>
                        )}
                        {lowStock && (
                          <span className="font-mono text-[0.62rem] font-semibold uppercase tracking-wide text-[#a8461a]">
                            Low
                          </span>
                        )}
                      </div>
                      {urgentPace && (
                        <span className="font-mono text-[0.62rem] text-[#a8461a]">
                          Selling ~{velocity.toFixed(1)}/day — ~{Math.max(1, Math.round(daysLeft!))}d left at this pace
                        </span>
                      )}
                    </div>
                  </td>
                  <td className="px-4 py-2.5 text-right">
                    <div className="flex flex-col items-end gap-1.5">
                      <button
                        onClick={() => setModal({ mode: "edit", product: p })}
                        className="font-mono text-[0.65rem] uppercase tracking-wide text-ink-soft hover:text-green"
                      >
                        Edit
                      </button>
                      <button
                        onClick={() => handleToggleSpecial(p)}
                        disabled={togglingSpecial === p.id}
                        className="font-mono text-[0.6rem] uppercase tracking-wide text-ink-soft hover:text-gold-ink disabled:opacity-60"
                      >
                        {p.is_special ? "Unset Special" : "Make Special"}
                      </button>
                      <button
                        onClick={() => handleToggleHealthy(p)}
                        disabled={togglingHealthy === p.id}
                        className="font-mono text-[0.6rem] uppercase tracking-wide text-ink-soft hover:text-green disabled:opacity-60"
                      >
                        {p.is_healthy ? "Unset Healthy Pick" : "Mark Healthy Pick"}
                      </button>
                    </div>
                  </td>
                </tr>
              );
            })}
            {shown.length === 0 && (
              <tr>
                <td colSpan={6} className="px-4 py-6 text-center font-body text-sm text-ink-soft">
                  No products match.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {matching.length > shown.length && (
        <div className="mt-4 flex flex-col items-center gap-1.5">
          <button
            type="button"
            onClick={() => setRowLimit((n) => n + ROW_PAGE * 2)}
            className="rounded-full border border-green px-4 py-1.5 font-mono text-xs font-semibold text-green transition hover:bg-green hover:text-white"
          >
            Show more
          </button>
          <p className="font-mono text-[0.65rem] text-ink-soft">
            Showing {shown.length} of {matching.length} — search or pick a category to narrow it down
          </p>
        </div>
      )}

        </>
      )}

      {modal && (
        <ProductFormModal
          mode={modal.mode}
          product={modal.mode === "edit" ? modal.product : undefined}
          categories={categories}
          onClose={() => setModal(null)}
          onSaved={onProductSaved}
          onDeleted={onProductRemoved}
          onCategoryCreated={onRefresh}
        />
      )}
    </div>
  );
}
